import type {
  Question,
  QuestionOption,
  QuestionAnswer,
} from "./question-form-state";
import {
  useQuestionFormHost,
  type QuestionFormHost,
  type QuestionShortcut,
} from "./question-form-host";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
  type RefObject,
} from "react";
import { Button } from "./button";
import { Icon } from "./icon";
import { VoiceInputTextarea } from "./voice-input-textarea";
import { usePointerCoarse } from "./hooks/use-pointer-coarse";
import { cn } from "../../lib/utils";
import {
  answerStateFor,
  buildQuestionAnswers,
  isQuestionAnswered,
  resolveQuestionShortcutChoice,
  type QuestionAnswerState,
  type QuestionFormState,
} from "./question-form-state";
import { useQuestionFormDraft } from "./question-form-draft";

const OTHER_OPTION_LABEL = "Other…";
const FREE_TEXT_MIN_HEIGHT = 84;
const FREE_TEXT_MAX_HEIGHT = 158;
const PREVIEW_MAX_HEIGHT = 220;

export type QuestionFormDensity = QuestionFormHost["density"];

interface QuestionOptionRowProps {
  checked: boolean;
  density: QuestionFormDensity;
  label: string;
  description?: string;
  multiSelect: boolean;
  onSelect: () => void;
  shortcut?: QuestionShortcut;
}

function useAutoGrow(
  ref: RefObject<HTMLTextAreaElement | null>,
  { minHeight, maxHeight }: { minHeight: number; maxHeight: number },
) {
  return useCallback(
    (textarea?: HTMLTextAreaElement | null) => {
      const element = textarea ?? ref.current;
      if (!element) return;
      element.style.height = "auto";
      element.style.height = `${Math.min(
        Math.max(element.scrollHeight, minHeight),
        maxHeight,
      )}px`;
    },
    [maxHeight, minHeight, ref],
  );
}

function QuestionOptionRow({
  checked,
  density,
  label,
  description,
  multiSelect,
  onSelect,
  shortcut,
}: QuestionOptionRowProps) {
  return (
    <button
      type="button"
      aria-pressed={checked}
      aria-keyshortcuts={shortcut?.ariaKeyshortcuts}
      onClick={onSelect}
      className={cn(
        "flex w-full rounded-md text-left transition-colors",
        density === "compact"
          ? "items-center gap-2 px-1.5 py-0.5"
          : "items-start gap-2.5 px-2.5 py-1.5",
        checked ? "bg-surface-selected" : "hover:bg-state-hover",
      )}
    >
      <span
        className={cn(
          "flex shrink-0 items-center justify-center border",
          density === "compact" ? "size-3.5" : "mt-0.5 size-4",
          multiSelect ? "rounded" : "rounded-full",
          checked
            ? "border-primary bg-primary text-primary-foreground"
            : "border-input",
        )}
      >
        {checked ? <Icon name="Check" className="size-3" aria-hidden /> : null}
      </span>
      {density === "compact" ? (
        <span className="flex min-w-0 flex-1 items-baseline gap-2">
          <span className="shrink-0 text-xs text-foreground/90">{label}</span>
          {description ? (
            <span className="min-w-0 truncate text-xs text-muted-foreground">
              {description}
            </span>
          ) : null}
        </span>
      ) : (
        <span className="min-w-0 flex-1">
          <span className="block text-sm font-medium text-foreground">
            {label}
          </span>
          {description ? (
            <span className="mt-0.5 block text-xs leading-snug text-muted-foreground">
              {description}
            </span>
          ) : null}
        </span>
      )}
      {shortcut ? (
        <kbd
          aria-hidden="true"
          className={cn(
            "shrink-0 text-xs font-normal text-subtle-foreground",
            density === "compact" ? undefined : "mt-0.5",
          )}
        >
          {shortcut.label}
        </kbd>
      ) : null}
    </button>
  );
}

function QuestionOptionPreview({ preview }: { preview: string }) {
  return (
    <pre
      className="mx-2.5 mb-1 mt-1 overflow-auto whitespace-pre-wrap break-words rounded-md border border-border bg-surface-raised px-2.5 py-2 font-mono text-xs leading-relaxed text-foreground"
      style={{ maxHeight: `${PREVIEW_MAX_HEIGHT}px` }}
    >
      {preview}
    </pre>
  );
}

interface QuestionTabsProps {
  disabled: boolean;
  currentIndex: number;
  formState: QuestionFormState;
  onSelect: (index: number) => void;
  questions: readonly Question[];
}

function QuestionTabs({
  disabled,
  currentIndex,
  formState,
  onSelect,
  questions,
}: QuestionTabsProps) {
  return (
    <div className="mb-2 flex shrink-0 items-center gap-2">
      <div className="flex min-w-0 flex-1 items-center gap-1 overflow-x-auto">
        {questions.map((question, index) => {
          const answered = isQuestionAnswered(
            question,
            answerStateFor(formState, question),
          );
          const isActive = index === currentIndex;
          return (
            <div
              key={question.id}
              className={cn(
                "relative inline-flex h-7 shrink-0 items-center rounded-md",
                isActive
                  ? "bg-muted text-foreground"
                  : "text-muted-foreground hover:bg-state-hover",
              )}
            >
              <button
                type="button"
                disabled={disabled}
                onClick={() => onSelect(index)}
                aria-pressed={isActive}
                title={question.prompt}
                className="flex h-full min-w-0 items-center rounded-md px-2 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
              >
                <span
                  className={cn(
                    "truncate text-xs",
                    answered ? "line-through" : undefined,
                  )}
                  style={{ maxWidth: "180px" }}
                >
                  {question.shortLabel}
                </span>
              </button>
            </div>
          );
        })}
      </div>
      <span className="shrink-0 text-xs text-muted-foreground">
        {currentIndex + 1} of {questions.length}
      </span>
    </div>
  );
}

interface QuestionInputBlockProps {
  actions: ReactNode;
  density: QuestionFormDensity;
  disabled: boolean;
  question: Question;
  state: QuestionAnswerState;
  onToggleOption: (optionValue: string) => void;
  onSelectOther: () => void;
  onFreeTextChange: (value: string) => void;
  onShortcutSubmit: () => void;
  onVoiceInputActiveChange: (active: boolean) => void;
  shortcuts: ReadonlyMap<string, QuestionShortcut>;
}

function QuestionInputBlock({
  actions,
  density,
  disabled,
  question,
  state,
  onToggleOption,
  onSelectOther,
  onFreeTextChange,
  onShortcutSubmit,
  onVoiceInputActiveChange,
  shortcuts,
}: QuestionInputBlockProps) {
  const freeTextRef = useRef<HTMLTextAreaElement>(null);
  const isPointerCoarse = usePointerCoarse();
  const resizeFreeTextArea = useAutoGrow(freeTextRef, {
    minHeight: FREE_TEXT_MIN_HEIGHT,
    maxHeight: FREE_TEXT_MAX_HEIGHT,
  });
  const options = question.options;
  const freeTextLabel = `${question.shortLabel} answer`;

  useLayoutEffect(() => {
    if (!state.otherSelected) return;
    resizeFreeTextArea();
  }, [question.id, resizeFreeTextArea, state.otherSelected, state.otherText]);

  const handleFreeTextKeyDown = (
    event: KeyboardEvent<HTMLTextAreaElement>,
  ): void => {
    if (
      event.nativeEvent.isComposing ||
      event.key !== "Enter" ||
      (!event.metaKey && !event.ctrlKey)
    ) {
      return;
    }
    event.preventDefault();
    onShortcutSubmit();
  };

  return (
    <fieldset disabled={disabled} className="min-w-0">
      <legend className="sr-only">{question.prompt}</legend>
      {density === "compact" ? (
        <div className="flex min-w-0 items-center gap-2">
          <div className="min-w-0 flex-1 truncate text-xs text-foreground">
            {question.prompt}
          </div>
          {actions}
        </div>
      ) : question.prompt ? (
        <div className="text-sm font-semibold text-foreground">
          {question.prompt}
        </div>
      ) : null}
      <div
        className={cn("space-y-0.5", density === "compact" ? "mt-1" : "mt-2")}
      >
        {options.map((option: QuestionOption, index) => {
          const checked = state.selected.includes(option.value);
          return (
            <div key={option.value}>
              <QuestionOptionRow
                checked={checked}
                density={density}
                label={option.label}
                description={option.description}
                multiSelect={question.multiSelect}
                onSelect={() => onToggleOption(option.value)}
                shortcut={shortcuts.get(String(index))}
              />
              {checked && option.preview ? (
                <QuestionOptionPreview preview={option.preview} />
              ) : null}
            </div>
          );
        })}
        {question.allowFreeText && options.length > 0 ? (
          <QuestionOptionRow
            checked={state.otherSelected}
            density={density}
            label={OTHER_OPTION_LABEL}
            multiSelect={question.multiSelect}
            onSelect={onSelectOther}
            shortcut={shortcuts.get(String(options.length))}
          />
        ) : null}
      </div>
      {state.otherSelected ? (
        <VoiceInputTextarea
          ref={freeTextRef}
          aria-label={freeTextLabel}
          value={state.otherText}
          rows={1}
          autoFocus={!isPointerCoarse}
          autoComplete="off"
          onValueChange={onFreeTextChange}
          onVoiceInputActiveChange={onVoiceInputActiveChange}
          onKeyDown={handleFreeTextKeyDown}
          placeholder="Type your own answer…"
          className="mt-2 block w-full resize-none overflow-y-auto rounded-md border border-border bg-surface-raised px-3 py-2 text-sm leading-relaxed text-foreground placeholder:text-muted-foreground focus-visible:border-ring/50 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring/40"
          style={{
            minHeight: `${FREE_TEXT_MIN_HEIGHT}px`,
            maxHeight: `${FREE_TEXT_MAX_HEIGHT}px`,
          }}
        />
      ) : null}
    </fieldset>
  );
}

export interface QuestionFormProps {
  draftKey?: string;
  questions: readonly Question[];
  disabled: boolean;
  cancelDisabled: boolean;
  onSubmit: (answers: Record<string, QuestionAnswer>) => void | Promise<void>;
  onCancel: () => void | Promise<void>;
}

export function QuestionForm({
  draftKey,
  questions,
  disabled: inputDisabled,
  cancelDisabled,
  onSubmit,
  onCancel,
}: QuestionFormProps) {
  const { formState, setFormState, currentIndex, setCurrentIndex, clearDraft } =
    useQuestionFormDraft(draftKey, questions);
  const [settledAction, setSettledAction] = useState<
    "submit" | "cancel" | null
  >(null);
  const disabled = inputDisabled || settledAction !== null;
  const [voiceBusy, setVoiceBusy] = useState(false);
  const formRef = useRef<HTMLDivElement>(null);
  const { density, shortcuts, registerChoiceHandler } = useQuestionFormHost();

  const totalQuestions = questions.length;
  const currentQuestion = questions[currentIndex] ?? null;
  const isFirst = currentIndex === 0;
  const isLast = currentIndex === totalQuestions - 1;
  const allAnswered = useMemo(
    () =>
      totalQuestions > 0 &&
      questions.every((question) =>
        isQuestionAnswered(question, answerStateFor(formState, question)),
      ),
    [formState, questions, totalQuestions],
  );

  const updateQuestionState = useCallback(
    (
      question: Question,
      update: (state: QuestionAnswerState) => QuestionAnswerState,
    ): void => {
      setFormState((current) => ({
        ...current,
        [question.id]: update(answerStateFor(current, question)),
      }));
    },
    [setFormState],
  );

  const handleToggleOption = useCallback(
    (question: Question, optionValue: string): void => {
      updateQuestionState(question, (state) => {
        if (question.multiSelect) {
          const selected = state.selected.includes(optionValue)
            ? state.selected.filter((value) => value !== optionValue)
            : [...state.selected, optionValue];
          return { ...state, selected };
        }
        return { ...state, selected: [optionValue], otherSelected: false };
      });
    },
    [updateQuestionState],
  );

  const handleSelectOther = useCallback(
    (question: Question): void => {
      updateQuestionState(question, (state) =>
        question.multiSelect
          ? { ...state, otherSelected: !state.otherSelected }
          : { ...state, selected: [], otherSelected: true },
      );
    },
    [updateQuestionState],
  );

  const handleFreeTextChange = (question: Question, value: string): void => {
    updateQuestionState(question, (state) => ({ ...state, otherText: value }));
  };

  const submitAnswer = async (): Promise<void> => {
    if (disabled || voiceBusy || !allAnswered) return;
    try {
      await onSubmit(buildQuestionAnswers(questions, formState));
      setSettledAction("submit");
      clearDraft();
    } catch {}
  };

  const handleAdvance = (): void => {
    if (disabled || voiceBusy) return;
    if (isLast) {
      void submitAnswer();
      return;
    }
    setCurrentIndex((index) => Math.min(index + 1, totalQuestions - 1));
  };

  useEffect(() => {
    if (disabled || voiceBusy || currentQuestion === null) return;
    return registerChoiceHandler((index) => {
      const choice = resolveQuestionShortcutChoice(currentQuestion, index);
      if (!choice) return false;
      if (choice.kind === "option") {
        handleToggleOption(currentQuestion, choice.value);
        formRef.current?.focus();
      } else handleSelectOther(currentQuestion);
      return true;
    });
  }, [
    disabled,
    voiceBusy,
    currentQuestion,
    registerChoiceHandler,
    handleToggleOption,
    handleSelectOther,
  ]);

  if (!currentQuestion) return null;

  const currentState = answerStateFor(formState, currentQuestion);
  const compactButtonClass =
    density === "compact" ? "h-6 px-2 text-xs" : undefined;
  const cancelButton = (
    <Button
      type="button"
      size="sm"
      variant="ghost"
      className={compactButtonClass}
      disabled={cancelDisabled || settledAction !== null}
      onClick={async () => {
        try {
          await onCancel();
          setSettledAction("cancel");
          clearDraft();
        } catch {}
      }}
    >
      {density === "compact" ? "Decline" : "Cancel"}
    </Button>
  );
  const backButton = !isFirst ? (
    <Button
      type="button"
      size="sm"
      variant="outline"
      className={compactButtonClass}
      disabled={disabled || voiceBusy}
      onClick={() => setCurrentIndex((index) => Math.max(index - 1, 0))}
    >
      Back
    </Button>
  ) : null;
  const advanceButton = (
    <Button
      type="button"
      size="sm"
      className={compactButtonClass}
      disabled={disabled || voiceBusy || (isLast && !allAnswered)}
      onClick={handleAdvance}
    >
      {inputDisabled || settledAction === "submit" ? (
        <Icon name="Spinner" className="size-3 animate-spin" />
      ) : null}
      {isLast ? (density === "compact" ? "Submit" : "Submit answer") : "Next"}
    </Button>
  );

  return (
    <div
      ref={formRef}
      tabIndex={-1}
      onKeyDown={(event) => {
        if (
          event.target !== event.currentTarget ||
          event.defaultPrevented ||
          event.nativeEvent.isComposing ||
          event.key !== "Enter" ||
          event.shiftKey ||
          event.metaKey ||
          event.ctrlKey ||
          event.altKey ||
          disabled
        )
          return;
        event.preventDefault();
        handleAdvance();
      }}
      className="-m-1 flex min-h-0 flex-col rounded-md p-1 text-xs text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-ring"
    >
      {totalQuestions > 1 ? (
        <QuestionTabs
          disabled={disabled || voiceBusy}
          currentIndex={currentIndex}
          formState={formState}
          onSelect={setCurrentIndex}
          questions={questions}
        />
      ) : null}
      <div>
        <QuestionInputBlock
          key={currentQuestion.id}
          actions={
            <div className="flex shrink-0 items-center gap-1">
              {cancelButton}
              {backButton}
              {advanceButton}
            </div>
          }
          density={density}
          disabled={disabled}
          question={currentQuestion}
          state={currentState}
          onToggleOption={(optionValue) =>
            handleToggleOption(currentQuestion, optionValue)
          }
          onSelectOther={() => handleSelectOther(currentQuestion)}
          onFreeTextChange={(value) =>
            handleFreeTextChange(currentQuestion, value)
          }
          onVoiceInputActiveChange={setVoiceBusy}
          onShortcutSubmit={handleAdvance}
          shortcuts={shortcuts}
        />
      </div>
      {density === "compact" ? null : (
        <div className="mt-3 flex shrink-0 items-center justify-between gap-2">
          {cancelButton}
          <div className="flex items-center gap-2">
            {backButton}
            {advanceButton}
          </div>
        </div>
      )}
    </div>
  );
}
